+		missing_signing_key(tree, actx->pinfo, private_data, \
+				    orig_pactvb, state->full_checksum_type, \
+				    state->kdc_ek->keytype, \
+				    __reason, \
+				    "kdc_checksum_key", \
+				    1, \
+				    0); \
+		return; \
+	} \
+	if (__length64 > G_MAXINT32) { \
+		missing_signing_key(tree, actx->pinfo, private_data, \
+				    orig_pactvb, state->full_checksum_type, \
+				    state->kdc_ek->keytype, \
+				    __reason, \
+				    "kdc_checksum_key", \
+				    1, \
+				    0); \
+		return; \
+	} \
+	__last = __offset64 + __length64; \
+	if (__last > __end) { \
+		missing_signing_key(tree, actx->pinfo, private_data, \
+				    orig_pactvb, state->full_checksum_type, \
+				    state->kdc_ek->keytype, \
+				    __reason, \
+				    "kdc_checksum_key", \
+				    1, \
+				    0); \
+		return; \
+	} \
