+	__PAC_CHECK_OFFSET_SIZE(cur_offset, 8, "PACTYPE Header");
+	num_buffers = tvb_get_guint32(copy_pactvb, cur_offset, ENC_LITTLE_ENDIAN);
+	cur_offset += 4;
